import { build } from 'esbuild';
import { pathToFileURL } from 'node:url';
const root = process.argv[2];
const mk = async (entry, out) => { await build({ entryPoints: [entry], bundle: true, format: 'esm', platform: 'node', write: true, outfile: out, absWorkingDir: root, logLevel: 'silent' }); return import(pathToFileURL(out).href + '?v=' + Math.random()); };
const A = await mk('src/module.ts', process.argv[3] + '/a.mjs');
const B = await mk('out/module.ts', process.argv[3] + '/b.mjs');
const names = ['jung','choi','kim','park','lee'];
const rnd = (n) => Math.floor(Math.random()*n);
const row = () => ({ id: rnd(10), name: names[rnd(5)], age: 18 + rnd(43) });
let bad = 0;
for (let i = 0; i < 20000; i++) {
  const r = row();
  if (JSON.stringify(A.publicFields(r)) !== JSON.stringify(B.publicFields(r))) { bad++; console.log('pf', r); }
