  const len = rnd(9);
  let s = ''; for (let j=0;j<len;j++) s += chars[rnd(chars.length)];
  const a = A.parseAmount(s), b = B.parseAmount(s);
  if (!Object.is(a,b)) { bad++; if (bad < 20) console.log('pa', JSON.stringify(s), a, b); }
}
